diff --git a/src/hb-raster-draw.cc b/src/hb-raster-draw.cc
index c39583daf..1ddeaff23 100644
--- a/src/hb-raster-draw.cc
+++ b/src/hb-raster-draw.cc
@@ -1242,25 +1242,24 @@ hb_raster_draw_glyph (hb_raster_draw_t *draw,
  *   α = min(|cover_accum·128 − area[x]|, 8192) · 255 / 8192
  */

-/* Add one edge piece's area/cover into a single cell. */
+/* Add one edge piece's area/cover into a single cell.  The caller has
+   resolved the surface window: col is inside it, or negative to fold a
+   left-of-surface winding contribution into column 0. */
 static HB_ALWAYS_INLINE void
 cell_add (int32_t *area, int16_t *cover, unsigned width, int col,
 	  int32_t fx0, int32_t fy0, int32_t fx1, int32_t fy1, int32_t wind,
 	  unsigned &x_min, unsigned &x_max)
 {
-  if (unlikely ((unsigned) col >= width))
+  if (unlikely (col < 0))
   {
-    if (unlikely (col < 0))
-    {
-      /* Edge is to the left of the surface.  The winding contribution
-       * still carries into the visible region, so add the cover delta
-       * to column 0.  Area is not added since the edge doesn't cross
-       * column 0's cell. */
-      int32_t dy = fy1 - fy0;
-      cover[0] += (int16_t) (dy * wind);
-      x_min = hb_min (x_min, 0u);
-      x_max = hb_max (x_max, 0u);
-    }
+    /* Edge is to the left of the surface.  The winding contribution
+     * still carries into the visible region, so add the cover delta
+     * to column 0.  Area is not added since the edge doesn't cross
+     * column 0's cell. */
+    int32_t dy = fy1 - fy0;
+    cover[0] += (int16_t) (dy * wind);
+    x_min = hb_min (x_min, 0u);
+    x_max = hb_max (x_max, 0u);
     return;
   }
   int32_t dy = fy1 - fy0;
@@ -1313,6 +1312,14 @@ edge_sweep_row (int32_t                *area,
   /* Fast path: both endpoints in the same pixel column. */
   if (cx0 == cx1)
   {
+    if (unlikely ((unsigned) (cx0 - x_org) >= width))
+    {
+      /* Off-surface single column: fold the winding contribution into
+       * column 0 when left of the surface, skip it when right of it. */
+      if (cx0 < x_org)
+	cell_add (area, cover, width, -1, 0, fy0, 0, fy1, wind, x_min, x_max);
+      return;
+    }
     cell_add (area, cover, width, cx0 - x_org, fx0, fy0, fx1, fy1, wind, x_min, x_max);
     return;
   }
@@ -1431,7 +1438,8 @@ edge_sweep_row (int32_t                *area,
     int32_t x_b = (int32_t) hb_clamp ((int64_t) cx0 * HB_RASTER_ONE_PIXEL,
 				      (int64_t) INT32_MIN, (int64_t) INT32_MAX);
     int32_t fy_b = fy0 + (int32_t) ((((int64_t) x_b - (int64_t) x0) * total_dy) / total_dx);
-    cell_add (area, cover, width, cx0 - x_org, fx0, fy0, 0, fy_b, wind, x_min, x_max);
+    if (likely (cx0 <= col_max))
+      cell_add (area, cover, width, cx0 - x_org, fx0, fy0, 0, fy_b, wind, x_min, x_max);

     int32_t cx = cx0 - 1;
     int32_t fy_prev = fy_b;

diff --git a/src/hb-raster-draw.cc b/src/hb-raster-draw.cc
index f974ed263..104dd23de 100644
--- a/src/hb-raster-draw.cc
+++ b/src/hb-raster-draw.cc
@@ -1322,14 +1322,6 @@ edge_sweep_row (Area                   *area,
   /* Fast path: both endpoints in the same pixel column. */
   if (cx0 == cx1)
   {
-    if (unlikely ((unsigned) (cx0 - x_org) >= width))
-    {
-      /* Off-surface single column: fold the winding contribution into
-       * column 0 when left of the surface, skip it when right of it. */
-      if (cx0 < x_org)
-	cell_add (area, cover, width, -1, 0, fy0, 0, fy1, wind, x_min, x_max);
-      return;
-    }
     cell_add (area, cover, width, cx0 - x_org, fx0, fy0, fx1, fy1, wind, x_min, x_max);
     return;
   }
